action.command:
python3 -c 'import json; from pathlib import Path; paths=sorted(Path("benchmark/challenges").glob("*.json"));
for p in paths:
 d=json.loads(p.read_text()); print(str(p),len(p.read_bytes()),type(d).__name__); print(list(d) if isinstance(d,dict) else len(d));
 if isinstance(d,dict):
  for k,v in d.items(): print(k,type(v).__name__,list(v)[:12] if isinstance(v,dict) else len(v) if isinstance(v,list) else str(v)[:180])'

python3 -c 'import json; from pathlib import Path; d=json.loads(Path("benchmark/challenges/library-icon-tests.json").read_text());
for c in d["controls"]:
 s=c["submitted"]; a=s.get("answer_record",{}); print("CONTROL",c["name"],"SUBMITTED_KEYS",list(s)); print("ANSWER_META",{k:v for k,v in a.items() if k!="claims"}); print("SPECIAL_CLAIMS",[x for x in a.get("claims",[]) if x.get("claim_id")=="A0005" or x.get("claim_id","").startswith("X")]); print("READER",{k:v for k,v in s.items() if "raw" not in k and k!="answer_record"}); print("OPERATION",c["probe"].get("simulated_operation")); print("ALIGNMENT_SPECIAL",[x for x in c["alignment"] if x.get("observation_id")=="R0005" or x.get("observation_id","").startswith("X")]); print("EVIDENCE",c["evidence"])
'

